# Diagnose selected-source identity before/after real original calls; never modify a namespace.
args<-commandArgs(TRUE);stopifnot(length(args)==4L);out<-args[1];.libPaths(args[2:3],include.site=FALSE);ns<-asNamespace("spdep");reference<-new.env(parent=ns);sys.source(args[4],reference,keep.source=FALSE)
sha<-function(raw)digest::digest(raw,algo="sha256",serialize=FALSE)
snapshot<-function(label){f<-get("lm.morantest",ns,inherits=FALSE);raw<-serialize(body(f),NULL,version=2);saveRDS(body(f),file.path(out,paste0(label,"-body.rds")));writeBin(raw,file.path(out,paste0(label,"-body.serialize2")));writeLines(deparse(body(f),width.cutoff=500),file.path(out,paste0(label,"-body.txt")));list(hash=sha(raw),source_body_identical=identical(body(reference$lm.morantest),body(f),ignore.srcref=FALSE,ignore.bytecode=FALSE),source_formals_identical=identical(formals(reference$lm.morantest),formals(f),ignore.srcref=FALSE,ignore.bytecode=FALSE))}
before<-snapshot("before");n<-48L;i<-seq_len(n);ids<-paste0("cell-",i);ids[3]<-" cell β ";nb<-lapply(i,function(j)as.integer(sort(c(if(j==1L)n else j-1L,if(j==n)1L else j+1L))));class(nb)<-"nb";attr(nb,"region.id")<-ids;attr(nb,"sym")<-TRUE;lw<-spdep::nb2listw(nb,glist=lapply(nb,function(x)rep(.5,length(x))),style="B",zero.policy=TRUE)
for(k in 1:6){y<-sin(i*.13*k);X<-cbind(1,i/n);fit<-stats::lm(y~0+X);spdep::lm.morantest(fit,lw,zero.policy=TRUE,alternative="greater")}
after<-snapshot("after");a<-readRDS(file.path(out,"before-body.rds"));b<-readRDS(file.path(out,"after-body.rds"));ar<-readBin(file.path(out,"before-body.serialize2"),"raw",n=100000);br<-readBin(file.path(out,"after-body.serialize2"),"raw",n=100000)
result<-list(status="OBSERVED_ORIGINAL_SOURCE_IDENTITY_AFTER_CALLS",before=before,after=after,saved_body_identical=identical(a,b,ignore.srcref=FALSE,ignore.bytecode=FALSE),saved_body_all_equal=as.list(all.equal(a,b,check.attributes=TRUE)),serialized_lengths=c(length(ar),length(br)),first_different_bytes=as.list(head(which(ar!=br),30)),namespace_patched=FALSE)
jsonlite::write_json(result,file.path(out,"RESULT.json"),pretty=TRUE,auto_unbox=TRUE,digits=NA);print(result)
